// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(this));
        address originalOwner = c.owner();
        vm.prank(originalOwner);
        try c.transferOwnership(newOwner) { } catch { }
        if (newOwner == originalOwner) {
            assertEq(c.owner(), originalOwner);
        } else {
            assertEq(c.owner(), newOwner);
        }
    }
}
